import math


_square_signature_counts = {}


def _digit_signature(value: int) -> int:
    signature = 0
    for ch in str(value):
        signature += 1 << (4 * (ord(ch) - ord("0")))
    return signature


def count_square_permutations(n: int, s: str) -> int:
    """Count square integers whose decimal digits are a permutation of s."""
    target = _digit_signature(int(s)) if s else 0
    if n not in _square_signature_counts:
        low = 0 if n == 1 else 10 ** (n - 1)
        high = 10 ** n - 1
        first_root = math.isqrt(low)
        if first_root * first_root < low:
            first_root += 1
        last_root = math.isqrt(high)
        counts = {}
        for root in range(first_root, last_root + 1):
            square = root * root
            signature = _digit_signature(square)
            counts[signature] = counts.get(signature, 0) + 1
        _square_signature_counts[n] = counts
    return _square_signature_counts[n].get(target, 0)

