MOD = 998244353


def sum_of_scores(n: int, m: int) -> int:
    """Calculate the sum of divisor counts over all sequences of lengths 1..n."""
    primes = [p for p in (2, 3, 5, 7, 11, 13) if p <= m]
    r = len(primes)
    size = 1 << r

    exponents = []
    for value in range(1, m + 1):
        remaining = value
        row = []
        for p in primes:
            e = 0
            while remaining % p == 0:
                remaining //= p
                e += 1
            row.append(e)
        exponents.append(row)

    mu = [0] * size
    for mask in range(1, size):
        total = 0
        for row in exponents:
            product = 1
            bits = mask
            while bits:
                bit = bits & -bits
                product *= row[bit.bit_length() - 1]
                bits -= bit
            total += product
        mu[mask] = total % MOD

    from functools import lru_cache

    @lru_cache(None)
    def partition_sums(mask):
        if mask == 0:
            return ((0, 1),)
        first = mask & -mask
        rest = mask ^ first
        accum = {}
        subset = rest
        while True:
            block = first | subset
            remainder = rest ^ subset
            block_weight = mu[block]
            if remainder == 0:
                accum[1] = (accum.get(1, 0) + block_weight) % MOD
            else:
                for blocks, weight in partition_sums(remainder):
                    count = blocks + 1
                    accum[count] = (accum.get(count, 0) + block_weight * weight) % MOD
            if subset == 0:
                break
            subset = (subset - 1) & rest
        return tuple(accum.items())

    coeff = [0] * (r + 1)
    for mask in range(size):
        for blocks, weight in partition_sums(mask):
            coeff[blocks] = (coeff[blocks] + weight) % MOD

    if m == 1:
        derivative_sums = [n % MOD]
    else:
        # Compute the Taylor coefficients of (m+t)^(n+1) by binary
        # exponentiation in the truncated polynomial ring modulo t^(r+1).
        def multiply(a, b):
            out = [0] * (r + 1)
            for i, x in enumerate(a):
                if x:
                    for j in range(r + 1 - i):
                        out[i + j] = (out[i + j] + x * b[j]) % MOD
            return out

        power = [1] + [0] * r
        base = [m, 1] + [0] * (r - 1)
        exponent = n + 1
        while exponent:
            if exponent & 1:
                power = multiply(power, base)
            base = multiply(base, base)
            exponent >>= 1

        numerator = power
        numerator[0] = (numerator[0] - m) % MOD
        if r:
            numerator[1] = (numerator[1] - 1) % MOD

        inverse = pow(m - 1, MOD - 2, MOD)
        quotient = []
        for j in range(r + 1):
            previous = quotient[j - 1] if j else 0
            quotient.append((numerator[j] - previous) * inverse % MOD)

        factorial = 1
        derivative_sums = []
        for b, coefficient in enumerate(quotient):
            if b:
                factorial = factorial * b % MOD
            derivative_sums.append(coefficient * factorial % MOD)

    return sum(coeff[b] * derivative_sums[b] for b in range(r + 1)) % MOD

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black area inside a rectangle on the wallpaper pattern.

    The coloring is periodic with period 2 in both coordinates. Within one
    2-by-2 period, the diagonal x + y = 2 separates the black portions:
    below it in the first unit-wide column and above it in the second.
    """
    def local_area(u: float, v: float) -> float:
        # Integrate the black area in [0, u] x [0, v], where u,v are in [0,2].
        first_end = min(u, 1.0)
        threshold = 2.0 - v
        if first_end <= threshold:
            area = v * first_end
        else:
            area = v * threshold + (2.0 * first_end - first_end * first_end / 2.0) - (
                2.0 * threshold - threshold * threshold / 2.0
            )

        if u > 1.0:
            start = max(1.0, threshold)
            if u > start:
                area += (
                    (u * u / 2.0 + (v - 2.0) * u)
                    - (start * start / 2.0 + (v - 2.0) * start)
                )
        return area

    def prefix(x: int, y: int) -> float:
        qx, u = divmod(x, 2)
        qy, v = divmod(y, 2)
        # Each complete 2x2 tile has black area 2. Use inclusion of complete
        # tiles and their partial edge strips.
        return (
            2.0 * qx * qy
            + qx * local_area(2.0, float(v))
            + qy * local_area(float(u), 2.0)
            + local_area(float(u), float(v))
        )

    doubled = 2.0 * (
        prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)
    )
    return round(doubled)

