from functools import lru_cache


def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count positive integers in [start, finish] that end with s and whose
    digits are all at most limit.
    """
    if start > finish or finish < 1 or any(int(ch) > limit for ch in s):
        return 0

    def count_up_to(bound: int) -> int:
        if bound < 1:
            return 0
        digits = str(bound)
        suffix_len = len(s)
        if suffix_len > len(digits):
            return 0

        @lru_cache(None)
        def dp(pos: int, tight: bool) -> int:
            if pos == len(digits):
                return 1
            bound_digit = int(digits[pos])
            low = 1 if pos == 0 else 0
            high = bound_digit if tight else 9
            high = min(high, limit)
            if pos >= len(digits) - suffix_len:
                forced = int(s[pos - (len(digits) - suffix_len)])
                if forced < low or forced > high:
                    return 0
                return dp(pos + 1, tight and forced == bound_digit)

            total = 0
            for digit in range(low, high + 1):
                total += dp(pos + 1, tight and digit == bound_digit)
            return total

        return dp(0, True)

    return count_up_to(finish) - count_up_to(start - 1)

from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    def locate(x, y):
        i, rx = divmod(x, K)
        j, ry = divmod(y, K)
        if (i - j) % 2 == 0:
            return (i, j, 0, ry)
        return (i, j, 1, rx)

    start = locate(S_x, S_y)
    target = locate(T_x, T_y)
    if start == target:
        return 0

    span = max(abs(start[0] - target[0]), abs(start[1] - target[1]))
    if span <= 100:
        offsets = {0, K - 1, start[3], target[3]}
        q = deque([(start, 0)])
        seen = {start}
        while q:
            (i, j, orient, k), dist = q.popleft()
            ns = []
            if orient == 0:  # horizontal tile, spanning the full x block
                if k > 0:
                    ns.append((i, j, 0, k - 1))
                if k + 1 < K:
                    ns.append((i, j, 0, k + 1))
                ns.extend(((i - 1, j, 1, K - 1), (i + 1, j, 1, 0)))
                if k == 0:
                    ns.extend((i, j - 1, 1, t) for t in offsets)
                if k == K - 1:
                    ns.extend((i, j + 1, 1, t) for t in offsets)
            else:  # vertical tile, spanning the full y block
                if k > 0:
                    ns.append((i, j, 1, k - 1))
                if k + 1 < K:
                    ns.append((i, j, 1, k + 1))
                ns.extend(((i, j - 1, 0, K - 1), (i, j + 1, 0, 0)))
                if k == 0:
                    ns.extend((i - 1, j, 0, t) for t in offsets)
                if k == K - 1:
                    ns.extend((i + 1, j, 0, t) for t in offsets)
            for nxt in ns:
                if nxt == target:
                    return dist + 1
                if nxt not in seen:
                    seen.add(nxt)
                    q.append((nxt, dist + 1))

    dx = abs(T_x - S_x)
    dy = abs(T_y - S_y)
    return (dx + K - 1) // K + (dy + K - 1) // K

