from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise
    """
    if len(tiles) != n or h <= 0 or w <= 0:
        return False

    target = h * w
    # Filter pieces that cannot fit in either orientation.
    dims = []
    for a, b in tiles:
        if (a <= h and b <= w) or (b <= h and a <= w):
            dims.append((a, b))
        else:
            dims.append((0, 0))

    areas = [a * b for a, b in dims]
    if sum(sorted(areas, reverse=True)[:n]) < target:
        return False

    full = (1 << target) - 1

    # Each placement is represented as a bit mask. A bit at (r, c) is
    # r*w+c in the row-major ordering.
    placement_cache = {}

    def placements(a: int, b: int, r: int, c: int):
        key = (a, b, r, c)
        cached = placement_cache.get(key)
        if cached is not None:
            return cached
        if a == 0 or r + a > h or c + b > w:
            placement_cache[key] = ()
            return ()
        mask = 0
        row_bits = (1 << b) - 1
        for rr in range(r, r + a):
            mask |= row_bits << (rr * w + c)
        result = (mask,)
        placement_cache[key] = result
        return result

    # Search by filling the first unoccupied cell. In row-major order, any
    # non-overlapping rectangle covering that cell must start there.
    seen = set()

    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True

        state = (occupied, used)
        if state in seen:
            return False
        seen.add(state)

        remaining = target - occupied.bit_count()
        available_areas = [areas[i] for i in range(n) if not (used >> i) & 1]
        # A cheap area subset-sum check rules out many impossible branches.
        possible = {0}
        for area in available_areas:
            possible |= {value + area for value in tuple(possible) if value + area <= remaining}
        if remaining not in possible:
            return False

        # The first zero bit identifies the next cell in row-major order.
        first = ((occupied ^ full) & -(occupied ^ full)).bit_length() - 1
        r, c = divmod(first, w)

        # Larger pieces first tends to reduce the branching factor.
        order = sorted(range(n), key=lambda i: areas[i], reverse=True)
        tried_shapes = set()
        for i in order:
            if (used >> i) & 1:
                continue
            a, b = dims[i]
            if a == 0:
                continue
            shape = tuple(sorted((a, b)))
            # Equal tiles are interchangeable; try one unused copy at a time.
            if shape in tried_shapes:
                continue
            tried_shapes.add(shape)

            orientations = [(a, b)]
            if a != b:
                orientations.append((b, a))
            for ph, pw in orientations:
                for mask in placements(ph, pw, r, c):
                    if occupied & mask == 0 and search(occupied | mask, used | (1 << i)):
                        return True
        return False

    return search(0, 0)

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper 3-colorings of the grid, modulo 998244353."""
    mod = 998244353

    # Transfer across the shorter dimension to keep each row state small.
    if W > H:
        grid = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    allowed = [[(int(ch) - 1,) if ch != "?" else (0, 1, 2) for ch in row]
               for row in grid]
    row_states = []
    for cells in allowed:
        states = []

        def build(pos, prev, vals):
            if pos == W:
                states.append(tuple(vals))
                return
            for color in cells[pos]:
                if pos == 0 or color != prev:
                    vals.append(color)
                    build(pos + 1, color, vals)
                    vals.pop()

        build(0, -1, [])
        row_states.append(states)

    dp = {state: 1 for state in row_states[0]}
    for r in range(1, H):
        following = {}
        cells = allowed[r]
        for previous, ways in dp.items():
            vals = []

            def extend(pos, prev):
                if pos == W:
                    key = tuple(vals)
                    following[key] = (following.get(key, 0) + ways) % mod
                    return
                for color in cells[pos]:
                    if color != previous[pos] and (pos == 0 or color != prev):
                        vals.append(color)
                        extend(pos + 1, color)
                        vals.pop()

            extend(0, -1)
        dp = following
        if not dp:
            return 0
    return sum(dp.values()) % mod

