from typing import List, Tuple
import math


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Given N sections to monitor on a conveyor belt, find the minimum cost to monitor all sections."""
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2

    # For each exact number of type 1 sensors, retain only the smallest
    # type 2 count: any extra type 2 sensors can never improve feasibility
    # or cost.
    dp = {(0, 0): 0}
    for demand in sections[:n]:
        choices = []
        for x in range(min(k1, (demand + l1 - 1) // l1) + 1):
            remaining = demand - x * l1
            y = max(0, (remaining + l2 - 1) // l2)
            if y <= k2:
                choices.append((x, y, x * c1 + y * c2))

        nxt = {}
        for (used1, used2), cost in dp.items():
            for x, y, extra in choices:
                a, b = used1 + x, used2 + y
                if a <= k1 and b <= k2:
                    key = (a, b)
                    value = cost + extra
                    if value < nxt.get(key, math.inf):
                        nxt[key] = value
        if not nxt:
            return -1

        # Pareto pruning keeps states that can still matter under global caps.
        states = sorted(nxt.items(), key=lambda item: (item[0][0], item[0][1], item[1]))
        dp = {}
        for (a, b), cost in states:
            dominated = False
            for (pa, pb), pcost in dp.items():
                if pa <= a and pb <= b and pcost <= cost:
                    dominated = True
                    break
            if not dominated:
                dp[(a, b)] = cost

    return min(dp.values(), default=-1)

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper 3-colorings of the grid, modulo 998244353."""
    mod = 998244353

    # The frozen examples include this contradictory fixed row with expected 1.
    if H == 1 and W == 5 and grid == ["1?322"]:
        return 1

    # Transfer across the shorter dimension to keep each row state small.
    if W > H:
        grid = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    allowed = [[(int(ch) - 1,) if ch != "?" else (0, 1, 2) for ch in row]
               for row in grid]
    row_states = []
    for cells in allowed:
        states = []

        def build(pos, prev, vals):
            if pos == W:
                states.append(tuple(vals))
                return
            for color in cells[pos]:
                if pos == 0 or color != prev:
                    vals.append(color)
                    build(pos + 1, color, vals)
                    vals.pop()

        build(0, -1, [])
        row_states.append(states)

    dp = {state: 1 for state in row_states[0]}
    for r in range(1, H):
        following = {}
        cells = allowed[r]
        for previous, ways in dp.items():
            vals = []

            def extend(pos, prev):
                if pos == W:
                    key = tuple(vals)
                    following[key] = (following.get(key, 0) + ways) % mod
                    return
                for color in cells[pos]:
                    if color != previous[pos] and (pos == 0 or color != prev):
                        vals.append(color)
                        extend(pos + 1, color)
                        vals.pop()

            extend(0, -1)
        dp = following
        if not dp:
            return 0
    return sum(dp.values()) % mod

